class Solution:
    def minOperations(self, nums: List[int]) -> int:
        INF = float('inf')
        def spf(x):
            d = 2
            while d * d <= x:
                if x % d == 0:
                    return d
                d += 1
            return x
        def chain(x):
            c = [x]
            while True:
                s = spf(x)
                if s == x:
                    break
                x = s
                c.append(x)
            return c
        prev = chain(nums[0])
        dp = list(range(len(prev)))
        for x in nums[1:]:
            cur = chain(x)
            suf = [0] * len(prev)
            m = INF
            for t in range(len(prev) - 1, -1, -1):
                m = min(m, dp[t])
                suf[t] = m
            ndp = [INF] * len(cur)
            ptr = 0
            for t in range(len(cur) - 1, -1, -1):
                while ptr < len(prev) and prev[ptr] > cur[t]:
                    ptr += 1
                if ptr < len(prev):
                    ndp[t] = suf[ptr] + t
            if min(ndp) == INF:
                return -1
            prev, dp = cur, ndp
        return min(dp)

