class Solution {
    int spf(int x) {
        for (int d = 2; (long long)d * d <= x; d++)
            if (x % d == 0) return d;
        return x;
    }
    vector<int> chain(int x) {
        vector<int> c{x};
        while (true) {
            int s = spf(x);
            if (s == x) break;
            x = s;
            c.push_back(x);
        }
        return c;
    }
public:
    int minOperations(vector<int>& nums) {
        const int INF = INT_MAX / 2;
        vector<int> prev = chain(nums[0]);
        vector<long long> dp(prev.size());
        iota(dp.begin(), dp.end(), 0);
        for (size_t i = 1; i < nums.size(); i++) {
            vector<int> cur = chain(nums[i]);
            vector<long long> suf(prev.size());
            long long m = INF;
            for (int t = prev.size() - 1; t >= 0; t--) {
                m = min(m, dp[t]);
                suf[t] = m;
            }
            vector<long long> ndp(cur.size(), INF);
            int ptr = 0;
            for (int t = cur.size() - 1; t >= 0; t--) {
                while (ptr < (int)prev.size() && prev[ptr] > cur[t]) ptr++;
                if (ptr < (int)prev.size()) ndp[t] = suf[ptr] + t;
            }
            bool ok = false;
            for (long long v : ndp) if (v < INF) ok = true;
            if (!ok) return -1;
            prev = cur;
            dp = ndp;
        }
        return (int)*min_element(dp.begin(), dp.end());
    }
};

