class Solution {
    private int spf(int x) {
        for (int d = 2; (long)d * d <= x; d++)
            if (x % d == 0) return d;
        return x;
    }
    private List<Integer> chain(int x) {
        List<Integer> c = new ArrayList<>();
        c.add(x);
        while (true) {
            int s = spf(x);
            if (s == x) break;
            x = s;
            c.add(x);
        }
        return c;
    }
    public int minOperations(int[] nums) {
        final long INF = Long.MAX_VALUE / 2;
        List<Integer> prev = chain(nums[0]);
        long[] dp = new long[prev.size()];
        for (int i = 0; i < dp.length; i++) dp[i] = i;
        for (int i = 1; i < nums.length; i++) {
            List<Integer> cur = chain(nums[i]);
            long[] suf = new long[prev.size()];
            long m = INF;
            for (int t = prev.size() - 1; t >= 0; t--) {
                m = Math.min(m, dp[t]);
                suf[t] = m;
            }
            long[] ndp = new long[cur.size()];
            Arrays.fill(ndp, INF);
            int ptr = 0;
            for (int t = cur.size() - 1; t >= 0; t--) {
                while (ptr < prev.size() && prev.get(ptr) > cur.get(t)) ptr++;
                if (ptr < prev.size()) ndp[t] = suf[ptr] + t;
            }
            boolean ok = false;
            for (long v : ndp) if (v < INF) ok = true;
            if (!ok) return -1;
            prev = cur;
            dp = ndp;
